INSERT INTO `chat_message` VALUES (22, 1, '1780060719675', 'assistant', '我是星火Spark X2.0，由科大讯飞自主研发的认知智能大模型。我能够通过自然对话与人类交流，解答复杂问题，并高效完成跨领域的认知智能任务。当前已具备多轮对话、逻辑推理和多维度信息整合能力，可为您提供专业领域的知识服务与决策支持。', NULL, '2026-05-29 21:18:47');
INSERT INTO `chat_message` VALUES (23, 1, '1780060719675', 'user', '这是谁', '/uploads/tutor_images/tutor_1_1780060719675_a84f43ec.jpg', '2026-05-29 21:20:13');
INSERT INTO `chat_message` VALUES (24, 1, '1780060719675', 'assistant', '你是在问我的身份吗？我是星火Spark X2.0，由中国的人工智能领军企业科大讯飞自主研发的认知智能大模型。作为第三代认知智能系统，我具备以下核心特征：\n\n1. **技术架构**  \n   基于深度学习框架，支持多模态交互，能理解文本、语音、图像等多元信息。\n\n2. **核心能力**  \n   - 复杂逻辑推理  \n   - 跨领域知识关联  \n   - 多轮对话记忆  \n   - 实时信息检索（数据截至2025年6月）\n\n3. **应用场景**  \n   已在教育、医疗、司法等领域落地，可提供专业知识解答、数据分析等服务。\n\n需要特别说明的是，我的研发方科大讯飞自1999年成立以来，始终专注于智能语音与人工智能核心技术的创新突破。目前我的最新版本已通过中国信通院可信AIGC认证，您可以放心进行专业领域的深度交流。', NULL, '2026-05-29 21:20:30');

-- ----------------------------
-- Table structure for comment
-- ----------------------------
DROP TABLE IF EXISTS `comment`;
CREATE TABLE `comment`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `post_id` bigint NULL DEFAULT NULL COMMENT '帖子ID',
  `heritage_id` bigint NULL DEFAULT NULL COMMENT '遗产ID(扩展)',
  `parent_id` bigint NULL DEFAULT NULL COMMENT '父评论ID(楼中楼)',
  `author_id` bigint NOT NULL COMMENT '作者ID',
  `author_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '作者名',
  `to_user_id` bigint NULL DEFAULT NULL COMMENT '回复目标用户ID',
  `to_username` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '回复目标用户名',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '评论内容',
  `status` int NOT NULL DEFAULT 1 COMMENT '状态: 1正常 0删除',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_post_id`(`post_id` ASC) USING BTREE,
  INDEX `idx_author_id`(`author_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '评论表' ROW_FORMAT = Dynamic;

