INSERT INTO `quiz_history` VALUES (9, 1, 31, '斐波那契数列', '#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    /* 在此编写代码 */\n    int a = 0, b = 1, c;\n    if (n >= 1) {\n        printf(\"%d\", a);  // 输出第一项\n    }\n    if (n >= 2) {\n        printf(\" %d\", b); // 输出第二项，前面加空格\n    }\n    for (int i = 3; i <= n; i++) {\n        c = a + b;\n        printf(\" %d\", c); // 输出后续项，前面加空格\n        a = b;\n        b = c;\n    }\n    // 如果 n == 0 不会发生，因为 n >= 1\n    return 0;\n}', 'correct', '0 1 1 2 3 5 8', '0 1 1 2 3 5 8', NULL, '2026-05-30 17:54:18');
INSERT INTO `quiz_history` VALUES (10, 1, 100, '表达式求值', '#include <stdio.h>\n#include <ctype.h>\n#include <string.h>\n#include <stdlib.h>\n\n#define MAXLEN 1000\n\n// 栈结构（用于运算符和操作数）\ntypedef struct {\n    int top;\n    int data[MAXLEN];\n} IntStack;\n\nvoid initStack(IntStack *s) { s->top = -1; }\nint isEmpty(IntStack *s) { return s->top == -1; }\nvoid push(IntStack *s, int val) { s->data[++(s->top)] = val; }\nint pop(IntStack *s) { return s->data[(s->top)--]; }\nint peek(IntStack *s) { return s->data[s->top]; }\n\n// 运算符优先级\nint priority(char op) {\n    if (op == \'+\' || op == \'-\') return 1;\n    if (op == \'*\' || op == \'/\') return 2;\n    return 0;\n}\n\n// 中缀转后缀（结果保存在字符串数组中，每个token用空格隔开，便于后续解析）\nvoid infixToPostfix(char *infix, char *postfix) {\n    IntStack opStack;\n    initStack(&opStack);\n    int i = 0, j = 0;\n    char token[MAXLEN];\n    int len = strlen(infix);\n    \n    while (i < len) {\n        char c = infix[i];\n        if (isdigit(c)) {\n            // 读取完整数字\n            int k = 0;\n            while (i < len && isdigit(infix[i])) {\n                token[k++] = infix[i++];\n            }\n            token[k] = \'\\0\';\n            // 将数字复制到postfix，并加空格分隔\n            strcpy(postfix + j, token);\n            j += k;\n            postfix[j++] = \' \';\n        } else if (c == \'(\') {\n            push(&opStack, c);\n            i++;\n        } else if (c == \')\') {\n            while (!isEmpty(&opStack) && peek(&opStack) != \'(\') {\n                postfix[j++] = pop(&opStack);\n                postfix[j++] = \' \';\n            }\n            pop(&opStack); // 弹出 \'(\'\n            i++;\n        } else if (c == \'+\' || c == \'-\' || c == \'*\' || c == \'/\') {\n            while (!isEmpty(&opStack) && priority(peek(&opStack)) >= priority(c) && peek(&opStack) != \'(\') {\n                postfix[j++] = pop(&opStack);\n                postfix[j++] = \' \';\n            }\n            push(&opStack, c);\n            i++;\n        } else {\n            // 忽略空格等（按题目无空格）\n            i++;\n        }\n    }\n    // 弹出剩余运算符\n    while (!isEmpty(&opStack)) {\n        postfix[j++] = pop(&opStack);\n        postfix[j++] = \' \';\n    }\n    postfix[j] = \'\\0\';\n}\n\n// 计算后缀表达式的值\nint evaluatePostfix(char *postfix) {\n    IntStack valStack;\n    initStack(&valStack);\n    char *token = strtok(postfix, \" \");\n    while (token != NULL) {\n        if (isdigit(token[0]) || (token[0] == \'-\' && strlen(token) > 1)) {\n            // 数字（支持负数？题目数字为正，但减法运算可能出现负数中间结果，但token是数字）\n            int num = atoi(token);\n            push(&valStack, num);\n        } else {\n            // 运算符\n            int b = pop(&valStack); // 右操作数\n            int a = pop(&valStack); // 左操作数\n            int result;\n            switch (token[0]) {\n                case \'+\': result = a + b; break;\n                case \'-\': result = a - b; break;\n                case \'*\': result = a * b; break;\n                case \'/\': result = a / b; break; // C整数除法向零取整\n                default: result = 0;\n            }\n            push(&valStack, result);\n        }\n        token = strtok(NULL, \" \");\n    }\n    return pop(&valStack);\n}\n\nint main() {\n    char infix[MAXLEN + 5];\n    char postfix[MAXLEN * 2]; // 后缀表达式可能更长\n    scanf(\"%s\", infix);\n    infixToPostfix(infix, postfix);\n    int result = evaluatePostfix(postfix);\n    printf(\"%d\\n\", result);\n    return 0;\n}', 'correct', '11', '11', NULL, '2026-05-30 17:58:09');
INSERT INTO `quiz_history` VALUES (11, 1, 83, '二进制文件复制', '#include <stdio.h>\n#include <stdlib.h>\n\n#define BUFFER_SIZE 4096\n\nint main() {\n    FILE *src = fopen(\"source.bin\", \"rb\");\n    if (src == NULL) {\n        printf(\"Error: source file not found\\n\");\n        return 1;\n    }\n\n    FILE *dst = fopen(\"dest.bin\", \"wb\");\n    if (dst == NULL) {\n        printf(\"Error: cannot create destination file\\n\");\n        fclose(src);\n        return 1;\n    }\n\n    char buffer[BUFFER_SIZE];\n    size_t bytesRead, totalBytes = 0;\n\n    while ((bytesRead = fread(buffer, 1, BUFFER_SIZE, src)) > 0) {\n        fwrite(buffer, 1, bytesRead, dst);\n        totalBytes += bytesRead;\n    }\n\n    fclose(src);\n    fclose(dst);\n\n    printf(\"Copied %zu bytes.\\n\", totalBytes);\n    return 0;\n}', 'wrong', '程序输出: Copied 12345 bytes.', 'Error: source file not found', NULL, '2026-05-30 17:59:04');
INSERT INTO `quiz_history` VALUES (12, 1, 83, '二进制文件复制', '#include <stdio.h>\n#include <stdlib.h>\n\n#define BUFFER_SIZE 4096\n\nint main() {\n    FILE *src = fopen(\"source.bin\", \"rb\");\n    if (src == NULL) {\n        printf(\"Error: source file not found\\n\");\n        return 1;\n    }\n\n    FILE *dst = fopen(\"dest.bin\", \"wb\");\n    if (dst == NULL) {\n        printf(\"Error: cannot create destination file\\n\");\n        fclose(src);\n        return 1;\n    }\n\n    char buffer[BUFFER_SIZE];\n    size_t bytesRead, totalBytes = 0;\n\n    while ((bytesRead = fread(buffer, 1, BUFFER_SIZE, src)) > 0) {\n        fwrite(buffer, 1, bytesRead, dst);\n        totalBytes += bytesRead;\n    }\n\n    fclose(src);\n    fclose(dst);\n\n    printf(\"Copied %zu bytes.\\n\", totalBytes);\n    return 0;\n}', 'wrong', '程序输出: Copied 12345 bytes.', 'Error: source file not found', NULL, '2026-05-30 17:59:11');
INSERT INTO `quiz_history` VALUES (13, 1, 24, '求1到n的整数和', '#include <stdio.h>\n\nint main() {\n    int n, sum = 0;\n    scanf(\"%d\", &n);\n    for (int i = 1; i <= n; i++) {\n        sum += i;\n    }\n    printf(\"%d\\n\", sum);\n    return 0;\n}', 'correct', '15', '15', NULL, '2026-05-30 17:59:34');
INSERT INTO `quiz_history` VALUES (14, 1, 14, '位运算实现无符号整数加法', '#include <stdio.h>\n\nunsigned int add(unsigned int a, unsigned int b) {\n    while (b != 0) {\n        unsigned int carry = a & b;  // 计算进位\n        a = a ^ b;                   // 无进位加法\n        b = carry << 1;              // 进位左移一位\n    }\n    return a;\n}\n\nint main() {\n    unsigned int a, b;\n    scanf(\"%u %u\", &a, &b);\n    printf(\"%u\\n\", add(a, b));\n    return 0;\n}', 'correct', '8', '8', NULL, '2026-05-30 17:59:56');
INSERT INTO `quiz_history` VALUES (15, 1, 15, '回文数判断：算术运算符与关系运算符', '#include <stdio.h>\n\nint isPalindrome(int x) {\n    // 负数一定不是回文数\n    if (x < 0) return 0;\n    // 如果最后一位是0且x本身不是0，则也不是回文（如10, 110等）\n    if (x % 10 == 0 && x != 0) return 0;\n\n    int reversed = 0;\n    while (x > reversed) {\n        reversed = reversed * 10 + x % 10;\n        x /= 10;\n    }\n    // 当数字长度为奇数时，reversed会比x多一位，需要除以10比较\n    return x == reversed || x == reversed / 10;\n}\n\nint main() {\n    int x;\n    scanf(\"%d\", &x);\n    if (isPalindrome(x)) {\n        printf(\"Yes\\n\");\n    } else {\n        printf(\"No\\n\");\n    }\n    return 0;\n}', 'correct', 'Yes', 'Yes', NULL, '2026-05-30 18:00:51');
INSERT INTO `quiz_history` VALUES (16, 1, 6, '简单计算器', '#include <stdio.h>\n\nint main() {\n    int a, b;\n    char op;\n    scanf(\"%d %d %c\", &a, &b, &op);\n    \n    switch (op) {\n        case \'+\':\n            printf(\"%d\\n\", a + b);\n            break;\n        case \'-\':\n            printf(\"%d\\n\", a - b);\n            break;\n        case \'*\':\n            printf(\"%d\\n\", a * b);\n            break;\n        case \'/\':\n            if (b == 0) {\n                printf(\"Error\\n\");\n            } else {\n                printf(\"%d\\n\", a / b);\n            }\n            break;\n        default:\n            // 理论上输入合法，无需处理\n            break;\n    }\n    return 0;\n}', 'correct', '3', '3', NULL, '2026-05-30 18:01:11');
INSERT INTO `quiz_history` VALUES (17, 1, 7, '求圆的周长和面积', '#include <stdio.h>\n\n#define PI 3.14159\n\nint main() {\n    double r, circumference, area;\n    scanf(\"%lf\", &r);\n    circumference = 2 * PI * r;\n    area = PI * r * r;\n    printf(\"%.2f %.2f\\n\", circumference, area);\n    return 0;\n}', 'correct', '20.11 32.17', '20.11 32.17', NULL, '2026-05-30 18:01:27');
INSERT INTO `quiz_history` VALUES (18, 1, 25, '打印乘法表', '#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    for (int i = 1; i <= n; i++) {\n        for (int j = 1; j <= n; j++) {\n            printf(\"%d*%d=%2d\", i, j, i * j);\n            if (j < n) {\n                printf(\" \");\n            }\n        }\n        printf(\"\\n\");\n    }\n    return 0;\n}', 'correct', '1*1= 1 1*2= 2 1*3= 3\n2*1= 2 2*2= 4 2*3= 6\n3*1= 3 3*2= 6 3*3= 9', '1*1= 1 1*2= 2 1*3= 3\n2*1= 2 2*2= 4 2*3= 6\n3*1= 3 3*2= 6 3*3= 9', NULL, '2026-05-30 18:01:52');
INSERT INTO `quiz_history` VALUES (19, 1, 27, '数字反转', '#include <stdio.h>\n\nint main() {\n    int x;\n    scanf(\"%d\", &x);\n    if (x == 0) {\n        printf(\"0\\n\");\n        return 0;\n    }\n    if (x < 0) {\n        printf(\"-\");\n        x = -x;\n    }\n    int rev = 0;\n    while (x > 0) {\n        rev = rev * 10 + x % 10;\n        x /= 10;\n    }\n    printf(\"%d\\n\", rev);\n    return 0;\n}', 'correct', '321', '321', NULL, '2026-05-30 18:02:22');
INSERT INTO `quiz_history` VALUES (20, 1, 41, '最大子段和', '#include <stdio.h>\n\nint maxSubArray(int arr[], int n) {\n    int maxSoFar = arr[0];\n    int maxEndingHere = arr[0];\n    for (int i = 1; i < n; i++) {\n        if (maxEndingHere + arr[i] > arr[i]) {\n            maxEndingHere = maxEndingHere + arr[i];\n        } else {\n            maxEndingHere = arr[i];\n        }\n        if (maxEndingHere > maxSoFar) {\n            maxSoFar = maxEndingHere;\n        }\n    }\n    return maxSoFar;\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int arr[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &arr[i]);\n    }\n    printf(\"%d\\n\", maxSubArray(arr, n));\n    return 0;\n}', 'correct', '6', '6', NULL, '2026-05-30 18:32:00');

-- ----------------------------
-- Table structure for resource_record
-- ----------------------------
DROP TABLE IF EXISTS `resource_record`;
CREATE TABLE `resource_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `course_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '课程名称',
  `knowledge_point` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '知识点',
  `resource_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '资源类型: mindmap/document/exercise/code',
  `image_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '生成结果的图片URL',
  `file_name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '下载文件名',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 16 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '资源生成记录表' ROW_FORMAT = Dynamic;

