-- ----------------------------
-- Table structure for student_profile
-- ----------------------------
DROP TABLE IF EXISTS `student_profile`;
CREATE TABLE `student_profile`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `knowledge_mastery` json NULL COMMENT '知识点掌握 [{\"name\":\"Java\",\"status\":\"良好\",\"score\":85}]',
  `overall_level` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '整体掌握度',
  `diagnosis_report` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '学习诊断报告',
  `study_rhythm` json NULL COMMENT '学习节奏 {\"studySlot\":\"晚间\",\"focusDuration\":\"45分钟\",\"habit\":\"碎片化\"}',
  `cognitive_style` json NULL COMMENT '认知偏好 {\"mediaPreference\":[\"视频\"],\"understanding\":\"先实例后理论\"}',
  `learning_goal` json NULL COMMENT '学习目标 {\"purpose\":\"就业\",\"weeklyHours\":\"10小时\"}',
  `error_pattern` json NULL COMMENT '易错类型 [{\"type\":\"概念混淆\",\"frequency\":\"高\",\"cause\":\"基础不扎实\"}]',
  `resource_preference` json NULL COMMENT '资源偏好 {\"difficulty\":\"基础\",\"contentLength\":\"中等\",\"acceptExtension\":true}',
  `feedback_preference` json NULL COMMENT '反馈偏好 {\"answerStyle\":\"引导思考\",\"feedbackFrequency\":\"即时\"}',
  `completed_dimensions` tinyint NOT NULL DEFAULT 0 COMMENT '已完成维度数',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'IN_PROGRESS' COMMENT '状态: IN_PROGRESS/COMPLETED',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '学生画像表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of student_profile
-- ----------------------------
INSERT INTO `student_profile` VALUES (1, 1, '[{\"name\": \"行政职业能力测验整体模块\", \"score\": 100, \"status\": \"上游稳固\"}]', '上游稳固型', '学习基础扎实，专注力和实战意识强。当前关键提升点是速度控制与粗心率的平衡，建议通过限时训练和审题流程固化来进一步稳定得分效率。', '{\"habit\": \"沉浸式深度学习\", \"studySlot\": \"持续攻坚\", \"focusDuration\": \"一气呵成\"}', '{\"understanding\": \"偏好快速解题技巧，注重实战效率\", \"mediaPreference\": [\"视频\"]}', '{\"purpose\": \"考公备考\", \"weeklyHours\": \"12\"}', '[{\"type\": \"审题粗心\", \"cause\": \"注意力瞬间分散或条件看错\", \"frequency\": \"偶发\"}]', '{\"difficulty\": \"贴近真题难度\", \"contentLength\": \"精讲短课\", \"acceptExtension\": true}', '{\"answerStyle\": \"点出关键思路和步骤\", \"feedbackFrequency\": \"即时反馈\"}', 9, 'COMPLETED', '2026-05-28 21:12:11', '2026-05-28 22:13:54');

-- ----------------------------
-- Table structure for user
-- ----------------------------
DROP TABLE IF EXISTS `user`;
CREATE TABLE `user`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '鐢ㄦ埛ID',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '濮撳悕',
  `email` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '閭',
  `password` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '瀵嗙爜(BCrypt鍔犲瘑)',
  `role` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'student' COMMENT '瑙掕壊: student/teacher/researcher',
  `avatar` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `token` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '鐧诲綍浠ょ墝',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '鏇存柊鏃堕棿',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_email`(`email` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '鐢ㄦ埛琛�' ROW_FORMAT = Dynamic;

